import java.util.Scanner;
public class JIfElseIfGrade1 {
	public static void main(String[] args) {
		//Paso 1: Leer la puntuacion 
		Scanner scan = new Scanner (System.in);
		System.out.println("Ingrese una puntuacion: "); 
		int score = scan.nextInt();
		scan.close();
		//Paso 2: Determinar la calificacion para la puntuacion 
		String grade;
		if (score >= 90) {
			grade = "A";
		} else if (score >= 80) {
			grade = "B";
		} else if (score >= 70) {
			grade = "C";
		} else if (score >= 60) {
			grade = "D";
		} else {
			grade = "F";
		}
		//Paso 3: Imprimir la calificacion
		System.out.println("Calificacion = " + grade);	
	}
}

